// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    uint256 initialSupply = 1000;

    function setUp() public {
        c = new ERCDDAToken(initialSupply, "Test", "TST");
    }

    function testFuzz_property(uint256 burnAmount, uint256 mintAmount) public {
        vm.assume(burnAmount <= initialSupply * 10 ** c.decimals());
        vm.assume(mintAmount <= type(uint256).max - c.totalSupply());

        vm.prank(c.owner());
        c.mintToken(c.owner(), mintAmount);

        uint256 supplyBeforeBurn = c.totalSupply();
        vm.prank(c.owner());
        c.burn(burnAmount);

        assertTrue(c.totalSupply() <= supplyBeforeBurn);
    }
}
